func newMux() *http.ServeMux {
	mux := http.NewServeMux()

	mux.HandleFunc("GET /api/{version}/users", listUsers)
	mux.HandleFunc("GET /api/v1/{resource}", getResource)

	mux.HandleFunc("/orders/{id}/cancel", cancelOrder)

	visits := map[string]int{}
	mux.HandleFunc("GET /pages/{slug}", func(w http.ResponseWriter, r *http.Request) {
		slug := r.PathValue("slug")
		visits[slug]++
		renderPage(w, slug)
	})

	return mux
}
